// Проверка команд Tauri (CI: .github/workflows/security.yml). Команда живёт в четырёх местах, и забыть одно легко:
//   1. src-tauri/src/lib.rs — generate_handler![…]        (без этого интерфейс её не вызовет)
//   2. src-tauri/build.rs   — COMMANDS                     (из него генерируется разрешение allow-<имя>)
//   3. src-tauri/capabilities/*.json — "allow-<имя>"       (без этого вызов молча отклоняется — ошибка только в работе)
//   4. src-tauri/permissions/autogenerated/<имя>.toml      (сгенерированный файл должен быть в git — иначе на чистой
//                                                           машине сборка его не найдёт)
// И обратно: в capabilities нет разрешений на команды, которых больше нет (лишнее право — это лишняя поверхность).
//
//   node scripts/check-commands.mjs     — код выхода 1, если что-то не сходится
import { readFileSync, readdirSync, existsSync } from "node:fs";
import { join, dirname } from "node:path";
import { fileURLToPath } from "node:url";
import { execFileSync } from "node:child_process";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const T = join(root, "src-tauri");
const read = (p) => readFileSync(p, "utf8");
const errors = [];
const err = (m) => errors.push(m);

// 1. generate_handler![ … ] — последний сегмент пути (whisper::friends::wa_image → wa_image)
const lib = read(join(T, "src", "lib.rs")).replace(/\/\/[^\n]*/g, "");
const gh = /generate_handler!\[([\s\S]*?)\]/.exec(lib);
if (!gh) { console.error("В lib.rs не найден generate_handler![…]"); process.exit(1); }
const handler = new Set(gh[1].split(",").map((s) => s.trim()).filter(Boolean).map((s) => s.split("::").pop()));

// 2. COMMANDS в build.rs
const build = read(join(T, "build.rs")).replace(/\/\/[^\n]*/g, "");
const cm = /const COMMANDS:\s*&\[&str\]\s*=\s*&\[([\s\S]*?)\];/.exec(build);
if (!cm) { console.error("В build.rs не найден COMMANDS"); process.exit(1); }
const commands = new Set([...cm[1].matchAll(/"([a-z0-9_]+)"/g)].map((m) => m[1]));

// 3. разрешения во всех capabilities (строки "allow-…" и объекты { identifier: "allow-…" })
const capDir = join(T, "capabilities");
const allowed = new Map();         // имя команды → файлы
for (const f of readdirSync(capDir).filter((x) => x.endsWith(".json"))) {
  const j = JSON.parse(read(join(capDir, f)));
  for (const p of j.permissions || []) {
    const id = typeof p === "string" ? p : p?.identifier;
    if (typeof id !== "string" || !/^allow-[a-z0-9-]+$/.test(id)) continue;   // плагины (core:…, opener:…) — не наши
    const name = id.slice(6).replace(/-/g, "_");
    allowed.set(name, [...(allowed.get(name) || []), f]);
  }
}

// 4. сгенерированные файлы разрешений и их место в git
const permDir = join(T, "permissions", "autogenerated");
let tracked = null;
try {
  tracked = new Set(execFileSync("git", ["ls-files", "src-tauri/permissions/autogenerated"], { cwd: root, encoding: "utf8" })
    .split(/\r?\n/).filter(Boolean).map((p) => p.split("/").pop().replace(/\.toml$/, "")));
} catch { /* не git — пропускаем эту часть */ }

for (const c of handler) {
  if (!commands.has(c)) err(`${c}: есть в generate_handler (lib.rs), но нет в COMMANDS (build.rs) — разрешение не сгенерируется`);
  if (!allowed.has(c)) err(`${c}: нет "allow-${c.replace(/_/g, "-")}" ни в одном capabilities/*.json — интерфейс не сможет её вызвать`);
}
for (const c of commands) {
  if (!handler.has(c)) err(`${c}: есть в COMMANDS (build.rs), но нет в generate_handler (lib.rs) — команды нет, а разрешение есть`);
  const f = join(permDir, c + ".toml");
  if (existsSync(f) && tracked && !tracked.has(c)) err(`${c}: файл permissions/autogenerated/${c}.toml не добавлен в git — на чистой машине сборка упадёт`);
}
for (const [c, files] of allowed) {
  if (!commands.has(c)) err(`allow-${c.replace(/_/g, "-")} (${files.join(", ")}): такой команды нет — лишнее разрешение`);
  if (files.length > 1) err(`allow-${c.replace(/_/g, "-")}: разрешение повторяется в ${files.join(", ")}`);
}

for (const e of errors) console.log("✖ " + e);
console.log(`Команд: ${handler.size}, в COMMANDS: ${commands.size}, разрешений: ${allowed.size}. Ошибок: ${errors.length}.`);
process.exit(errors.length ? 1 : 0);
